// Bundles the game's scripts for players (the owner, 2026-11-11: "the page loads 96 separate scripts, 3.3 megabytes on an iPad over the network. A single bundled file at deploy time would load faster.
// We can work on that, right?"). `node tools/bundle.js`, and tools/stamp.js runs it for every build. The site is the repository as it is (GitHub Pages, no build step), so what it makes is committed:
//   dist/conduit.js  every script game.html loads before its boot check, in the same order, as one file, with the comments taken out by TypeScript's printer (its parser reads the code, so a string,
//                 a template or a regular expression is never cut; strict mode is NOT added; the code's meaning is untouched, only its layout). Without TypeScript the files go in as they are.
//   play.html     game.html with those script tags replaced by the one bundle; its boot check and js/init.js as they were. The page players open: game.html sends a visitor there over the web
//                 (https) unless ?dev, and the website (index.html) links to it.
// game.html stays the working page: the tests open it, file by file, and so does ?dev on the live site. Do not edit dist/conduit.js or play.html by hand: change the sources and run this.
// (dist/, not js/: the tests that read every file in js/ would find the whole game twice.)
const fs = require('fs'), path = require('path');
const ROOT = path.join(__dirname, '..');
const rd = f => fs.readFileSync(path.join(ROOT, f), 'utf8');
const TAG = /<script src="(js\/[^"?]+)\?v=([^"]*)"><\/script>/;

function loadTs() {
    for (const p of [process.env.TYPESCRIPT_PATH, 'typescript', '/opt/node22/lib/node_modules/typescript']) { if (!p) continue; try { return require(p); } catch (e) { /* the next */ } }
    return null;
}
// a script without its comments (TypeScript's printer), or as it is when TypeScript is not installed
function strip(ts, src, file) {
    if (!ts) return src;
    const out = ts.transpileModule(src, { fileName: file, reportDiagnostics: true, compilerOptions: { target: ts.ScriptTarget.ESNext, module: ts.ModuleKind.None, removeComments: true, alwaysStrict: false, strict: false, ignoreDeprecations: '6.0' } });
    const errs = (out.diagnostics || []).filter(d => d.category === ts.DiagnosticCategory.Error);
    if (errs.length) throw new Error(file + ': ' + errs.map(d => ts.flattenDiagnosticMessageText(d.messageText, ' ')).join('; '));
    if (/^\s*["']use strict["']/.test(out.outputText)) throw new Error(file + ': the printer added "use strict"');
    return out.outputText;
}
// what game.html loads: [{ file, line }] in order; the bundle is every one but the last (js/init.js), which runs after the boot check
function sources(html) {
    const lines = html.split('\n'), tags = [];
    lines.forEach((l, i) => { const m = l.match(TAG); if (m) tags.push({ file: m[1], build: m[2], line: i }); });
    if (!tags.length) throw new Error('game.html loads no scripts');
    const last = tags[tags.length - 1];
    if (last.file !== 'js/init.js') throw new Error('game.html\'s last script is ' + last.file + ', not js/init.js');
    if (!/BOOT CHECK/.test(lines.slice(tags[tags.length - 2].line, last.line).join('\n'))) throw new Error('game.html has no boot check between its last two scripts');
    return { lines, tags, bundled: tags.slice(0, -1) };
}
// what the two files should hold now
function build() {
    const html = rd('game.html'), S = sources(html), ts = loadTs(), build = S.tags[0].build;
    if (S.tags.some(t => t.build !== build)) throw new Error('game.html\'s scripts name more than one build: stamp it first (node tools/stamp.js)');
    let js = '// GENERATED by tools/bundle.js from the scripts game.html loads (build ' + build + '), in their order, ' + (ts ? 'without their comments' : 'as they are') + '. Do not edit: change js/*.js and run node tools/bundle.js.\n';
    for (const t of S.bundled) js += '/* ' + t.file + ' */\n' + strip(ts, rd(t.file), t.file).replace(/\s*$/, '') + '\n;\n';   // (a ; between files: one that ends without its own cannot run into the next)
    const first = S.bundled[0].line, inBundle = new Set(S.bundled.map(t => t.line)), out = [];
    S.lines.forEach((l, i) => {
        if (i === first) out.push('<script src="dist/conduit.js?v=' + build + '"></script>   <!-- the game\'s scripts as one file (tools/bundle.js); game.html loads them one by one -->');
        else if (!inBundle.has(i)) out.push(l);
    });
    let play = out.join('\n');
    play = play.replace(/<html lang="en">/, '<html lang="en">\n<!-- GENERATED by tools/bundle.js from game.html (build ' + build + '): the page players open. Do not edit: change game.html and run node tools/bundle.js. -->');
    return { js, play, build, files: S.bundled.map(t => t.file), stripped: !!ts };
}
function write() {
    const b = build();
    fs.mkdirSync(path.join(ROOT, 'dist'), { recursive: true }); fs.writeFileSync(path.join(ROOT, 'dist/conduit.js'), b.js); fs.writeFileSync(path.join(ROOT, 'play.html'), b.play);
    return b;
}
module.exports = { build, write, sources };
if (require.main === module) {
    const b = write(), kb = n => Math.round(n / 1024) + ' KB';
    const raw = b.files.reduce((n, f) => n + fs.statSync(path.join(ROOT, f)).size, 0);
    console.log('bundled ' + b.files.length + ' scripts (build ' + b.build + ') into dist/conduit.js: ' + kb(raw) + ' → ' + kb(Buffer.byteLength(b.js)) + (b.stripped ? ' (comments taken out)' : ' (TypeScript not found: as they are)') + '; play.html written');
}
